+func TestFSharpSameLineNestedModuleIsNotAnAbbreviation(t *testing.T) {
+	t.Parallel()
+	repo := t.TempDir()
+	writeFile(t, repo, "src/A.fs", `module Json = let serialize (x: int) = x + 1
+
+module Other =
